1	//! Ear-clipping polygon triangulator.
2	//!
3	//! A `std`-only port of the `mapbox::earcut` 2.2.x algorithm: build a circular
4	//! doubly-linked list from the outer ring, splice holes in as bridges, then clip
5	//! ears one by one. When no ear can be found the algorithm escalates through
6	//! three fallbacks — filter collinear points, cure local self-intersections,
7	//! and finally split the ring on a valid diagonal — which is what makes a
8	//! self-intersecting input such as a spiral triangulable at all.
9	//!
10	//! The triangle indices are emitted in exactly the order the reference
11	//! implementation emits them; the fallback passes are order-sensitive, so the
12	//! control flow is kept structurally identical rather than idiomatically
13	//! restructured.
14	
15	pub mod geom;
16	pub mod node;
17	pub mod zorder;
18	
19	use node::{Node, NIL};
20	
21	/// Triangulate a polygon given as a list of rings (outer ring first, holes after)
22	/// and return a flat list of triangle vertex indices into the concatenated rings.
23	pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<u32> {
24	    let mut earcut = Earcut::new();
25	    earcut.run(points);
26	    earcut.indices
27	}
28	
29	pub struct Earcut {
30	    pub indices: Vec<u32>,
31	    pub vertices: usize,
32	
33	    /// Arena backing the linked list; `usize` indices replace the original `Node*`.
34	    pub(crate) nodes: Vec<Node>,
35	
36	    hashing: bool,
37	    min_x: f64,
38	    max_x: f64,
39	    min_y: f64,
40	    max_y: f64,
41	    inv_size: f64,
42	}
43	
44	impl Default for Earcut {
45	    fn default() -> Self {
46	        Self::new()
47	    }
48	}
49	
50	impl Earcut {
51	    pub fn new() -> Self {
52	        Earcut {
53	            indices: Vec::new(),
54	            vertices: 0,
55	            nodes: Vec::new(),
56	            hashing: false,
57	            min_x: 0.0,
58	            max_x: 0.0,
59	            min_y: 0.0,
60	            max_y: 0.0,
61	            inv_size: 0.0,
62	        }
63	    }
64	
65	    /// Allocate a node in the arena and return its index.
66	    pub(crate) fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
67	        self.nodes.push(Node::new(i, x, y));
68	        self.nodes.len() - 1
69	    }
70	
71	    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
72	        // reset
73	        self.indices.clear();
74	        self.vertices = 0;
75	        self.nodes.clear();
76	        self.hashing = false;
77	        self.inv_size = 0.0;
78	
79	        if points.is_empty() {
80	            return;
81	        }
82	
83	        // The z-order hash only pays off past a vertex count threshold; the loop
84	        // stops early once the budget is blown, matching the reference exactly.
85	        let mut threshold: i32 = 80;
86	        let mut len: usize = 0;
87	        let mut i = 0;
88	        while threshold >= 0 && i < points.len() {
89	            threshold -= points[i].len() as i32;
90	            len += points[i].len();
91	            i += 1;
92	        }
93	
94	        // estimate size of nodes and indices
95	        self.nodes.reserve(len * 3 / 2);
96	        self.indices.reserve(len + points[0].len());
97	
98	        let mut outer_node = self.linked_list(&points[0], true);
99	        if outer_node == NIL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
100	            return;
101	        }
102	
103	        if points.len() > 1 {
104	            outer_node = self.eliminate_holes(points, outer_node);
105	        }
106	
107	        // if the shape is not too simple, we'll use z-order curve hash later;
108	        // calculate polygon bbox
109	        self.hashing = threshold < 0;
110	        if self.hashing {
111	            let mut p = self.nodes[outer_node].next;
112	            self.min_x = self.nodes[outer_node].x;
113	            self.max_x = self.min_x;
114	            self.min_y = self.nodes[outer_node].y;
115	            self.max_y = self.min_y;
116	            loop {
117	                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
118	                self.min_x = self.min_x.min(x);
119	                self.min_y = self.min_y.min(y);
120	                self.max_x = self.max_x.max(x);
121	                self.max_y = self.max_y.max(y);
122	                p = self.nodes[p].next;
123	                if p == outer_node {
124	                    break;
125	                }
126	            }
127	
128	            // min_x, min_y and inv_size are later used to transform coords into
129	            // integers for z-order calculation
130	            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
131	            self.inv_size = if self.inv_size != 0.0 {
132	                32767.0 / self.inv_size
133	            } else {
134	                0.0
135	            };
136	        }
137	
138	        self.earcut_linked(outer_node, 0);
139	    }
140	
141	    /// Create a circular doubly-linked list from polygon points in the specified
142	    /// winding order.
143	    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
144	        let mut sum = 0.0;
145	        let len = points.len();
146	        let mut last = NIL;
147	
148	        // calculate original winding order of a polygon ring
149	        let mut j = if len > 0 { len - 1 } else { 0 };
150	        for i in 0..len {
151	            let p1 = &points[i];
152	            let p2 = &points[j];
153	            let p20 = p2[0];
154	            let p10 = p1[0];
155	            let p11 = p1[1];
156	            let p21 = p2[1];
157	            sum += (p20 - p10) * (p11 + p21);
158	            j = i;
159	        }
160	
161	        // link points into circular doubly-linked list in the specified winding order
162	        if clockwise == (sum > 0.0) {
163	            for i in 0..len {
164	                last = self.insert_node(self.vertices + i, &points[i], last);
165	            }
166	        } else {
167	            for i in (0..len).rev() {
168	                last = self.insert_node(self.vertices + i, &points[i], last);
169	            }
170	        }
171	
172	        if last != NIL {
173	            let next = self.nodes[last].next;
174	            if self.equals(last, next) {
175	                self.remove_node(last);
176	                last = next;
177	            }
178	        }
179	
180	        self.vertices += len;
181	
182	        last
183	    }
184	
185	    /// Create a node and optionally link it with a previous one (in a circular
186	    /// doubly-linked list).
187	    fn insert_node(&mut self, i: usize, pt: &[f64; 2], last: usize) -> usize {
188	        let p = self.construct(i as u32, pt[0], pt[1]);
189	
190	        if last == NIL {
191	            self.nodes[p].prev = p;
192	            self.nodes[p].next = p;
193	        } else {
194	            let next = self.nodes[last].next;
195	            self.nodes[p].next = next;
196	            self.nodes[p].prev = last;
197	            self.nodes[next].prev = p;
198	            self.nodes[last].next = p;
199	        }
200	
201	        p
202	    }
203	
204	    /// Eliminate colinear or duplicate points. Pass `NIL` for `end` to default it
205	    /// to `start`.
206	    fn filter_points(&mut self, start: usize, end: usize) -> usize {
207	        if start == NIL {
208	            return start;
209	        }
210	        let mut end = if end == NIL { start } else { end };
211	
212	        let mut p = start;
213	        loop {
214	            let again;
215	            let prev = self.nodes[p].prev;
216	            let next = self.nodes[p].next;
217	
218	            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
219	                self.remove_node(p);
220	                p = prev;
221	                end = prev;
222	
223	                if p == self.nodes[p].next {
224	                    break;
225	                }
226	                again = true;
227	            } else {
228	                p = next;
229	                again = false;
230	            }
231	
232	            if !(again || p != end) {
233	                break;
234	            }
235	        }
236	
237	        end
238	    }
239	
240	    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
241	    fn earcut_linked(&mut self, ear: usize, pass: i32) {
242	        let mut ear = ear;
243	        if ear == NIL {
244	            return;
245	        }
246	
247	        // interlink polygon nodes in z-order
248	        if pass == 0 && self.hashing {
249	            self.index_curve(ear);
250	        }
251	
252	        let mut stop = ear;
253	
254	        // iterate through ears, slicing them one by one
255	        while self.nodes[ear].prev != self.nodes[ear].next {
256	            let prev = self.nodes[ear].prev;
257	            let next = self.nodes[ear].next;
258	
259	            let found = if self.hashing {
260	                self.is_ear_hashed(ear)
261	            } else {
262	                self.is_ear(ear)
263	            };
264	
265	            if found {
266	                // cut off the triangle
267	                self.indices.push(self.nodes[prev].i);
268	                self.indices.push(self.nodes[ear].i);
269	                self.indices.push(self.nodes[next].i);
270	
271	                self.remove_node(ear);
272	
273	                // skipping the next vertex leads to less sliver triangles
274	                ear = self.nodes[next].next;
275	                stop = ear;
276	
277	                continue;
278	            }
279	
280	            ear = next;
281	
282	            // if we looped through the whole remaining polygon and can't find any
283	            // more ears
284	            if ear == stop {
285	                if pass == 0 {
286	                    // try filtering points and slicing again
287	                    let filtered = self.filter_points(ear, NIL);
288	                    self.earcut_linked(filtered, 1);
289	                } else if pass == 1 {
290	                    // if this didn't work, try curing all small self-intersections
291	                    // locally
292	                    let filtered = self.filter_points(ear, NIL);
293	                    let cured = self.cure_local_intersections(filtered);
294	                    self.earcut_linked(cured, 2);
295	                } else if pass == 2 {
296	                    // as a last resort, try splitting the remaining polygon into two
297	                    self.split_earcut(ear);
298	                }
299	
300	                break;
301	            }
302	        }
303	    }
304	
305	    /// Check whether a polygon node forms a valid ear with adjacent nodes.
306	    fn is_ear(&self, ear: usize) -> bool {
307	        let a = self.nodes[ear].prev;
308	        let b = ear;
309	        let c = self.nodes[ear].next;
310	
311	        if self.area(a, b, c) >= 0.0 {
312	            return false; // reflex, can't be an ear
313	        }
314	
315	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
316	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
317	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
318	
319	        // now make sure we don't have other points inside the potential ear
320	        let mut p = self.nodes[c].next;
321	
322	        while p != a {
323	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
324	            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
325	            if self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
326	                && self.area(pp, p, pn) >= 0.0
327	            {
328	                return false;
329	            }
330	            p = pn;
331	        }
332	
333	        true
334	    }
335	
336	    /// Same as [`Earcut::is_ear`] but only visiting points whose z-order falls in
337	    /// the triangle's bounding box range.
338	    fn is_ear_hashed(&self, ear: usize) -> bool {
339	        let a = self.nodes[ear].prev;
340	        let b = ear;
341	        let c = self.nodes[ear].next;
342	
343	        if self.area(a, b, c) >= 0.0 {
344	            return false; // reflex, can't be an ear
345	        }
346	
347	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
348	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
349	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
350	
351	        // triangle bbox; min & max are calculated like this for speed
352	        let min_tx = ax.min(bx.min(cx));
353	        let min_ty = ay.min(by.min(cy));
354	        let max_tx = ax.max(bx.max(cx));
355	        let max_ty = ay.max(by.max(cy));
356	
357	        // z-order range for the current triangle bbox
358	        let min_z = self.z_order(min_tx, min_ty);
359	        let max_z = self.z_order(max_tx, max_ty);
360	
361	        // first look for points inside the triangle in increasing z-order
362	        let mut p = self.nodes[ear].next_z;
363	
364	        while p != NIL && self.nodes[p].z <= max_z {
365	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
366	            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
367	            if p != a
368	                && p != c
369	                && self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
370	                && self.area(pp, p, pn) >= 0.0
371	            {
372	                return false;
373	            }
374	            p = self.nodes[p].next_z;
375	        }
376	
377	        // then look for points in decreasing z-order
378	        p = self.nodes[ear].prev_z;
379	
380	        while p != NIL && self.nodes[p].z >= min_z {
381	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
382	            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
383	            if p != a
384	                && p != c
385	                && self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
386	                && self.area(pp, p, pn) >= 0.0
387	            {
388	                return false;
389	            }
390	            p = self.nodes[p].prev_z;
391	        }
392	
393	        true
394	    }
395	
396	    /// Go through all polygon nodes and cure small local self-intersections.
397	    fn cure_local_intersections(&mut self, start: usize) -> usize {
398	        let mut start = start;
399	        let mut p = start;
400	
401	        loop {
402	            let a = self.nodes[p].prev;
403	            let pn = self.nodes[p].next;
404	            let b = self.nodes[pn].next;
405	
406	            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
407	            if !self.equals(a, b)
408	                && self.intersects(a, p, pn, b)
409	                && self.locally_inside(a, b)
410	                && self.locally_inside(b, a)
411	            {
412	                self.indices.push(self.nodes[a].i);
413	                self.indices.push(self.nodes[p].i);
414	                self.indices.push(self.nodes[b].i);
415	
416	                // remove two nodes involved; `pn` is still `p.next` after the first
417	                // removal, which only rewires the neighbours
418	                self.remove_node(p);
419	                self.remove_node(pn);
420	
421	                p = b;
422	                start = b;
423	            }
424	
425	            p = self.nodes[p].next;
426	            if p == start {
427	                break;
428	            }
429	        }
430	
431	        self.filter_points(p, NIL)
432	    }
433	
434	    /// Try splitting polygon into two and triangulate them independently.
435	    fn split_earcut(&mut self, start: usize) {
436	        // look for a valid diagonal that divides the polygon into two
437	        let mut a = start;
438	        loop {
439	            let an = self.nodes[a].next;
440	            let mut b = self.nodes[an].next;
441	
442	            while b != self.nodes[a].prev {
443	                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
444	                    // split the polygon in two by the diagonal
445	                    let mut c = self.split_polygon(a, b);
446	
447	                    // filter colinear points around the cuts
448	                    let a_next = self.nodes[a].next;
449	                    let a2 = self.filter_points(a, a_next);
450	                    let c_next = self.nodes[c].next;
451	                    c = self.filter_points(c, c_next);
452	
453	                    // run earcut on each half
454	                    self.earcut_linked(a2, 0);
455	                    self.earcut_linked(c, 0);
456	                    return;
457	                }
458	                b = self.nodes[b].next;
459	            }
460	            a = self.nodes[a].next;
461	            if a == start {
462	                return;
463	            }
464	        }
465	    }
466	
467	    /// Link every hole into the outer loop, producing a single-ring polygon
468	    /// without holes.
469	    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
470	        let mut queue: Vec<usize> = Vec::new();
471	
472	        for ring in &points[1..] {
473	            let list = self.linked_list(ring, false);
474	            if list != NIL {
475	                if list == self.nodes[list].next {
476	                    self.nodes[list].steiner = true;
477	                }
478	                let leftmost = self.get_leftmost(list);
479	                queue.push(leftmost);
480	            }
481	        }
482	
483	        {
484	            let nodes = &self.nodes;
485	            queue.sort_by(|&a, &b| {
486	                nodes[a]
487	                    .x
488	                    .partial_cmp(&nodes[b].x)
489	                    .unwrap_or(std::cmp::Ordering::Equal)
490	            });
491	        }
492	
493	        // process holes from left to right
494	        let mut outer_node = outer_node;
495	        for hole in queue {
496	            outer_node = self.eliminate_hole(hole, outer_node);
497	        }
498	
499	        outer_node
500	    }
501	
502	    /// Find a bridge between vertices that connects a hole with an outer ring and
503	    /// link it.
504	    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
505	        let bridge = self.find_hole_bridge(hole, outer_node);
506	        if bridge == NIL {
507	            return outer_node;
508	        }
509	
510	        let bridge_reverse = self.split_polygon(bridge, hole);
511	
512	        // filter collinear points around the cuts
513	        let br_next = self.nodes[bridge_reverse].next;
514	        self.filter_points(bridge_reverse, br_next);
515	        let b_next = self.nodes[bridge].next;
516	        self.filter_points(bridge, b_next)
517	    }
518	
519	    /// David Eberly's algorithm for finding a bridge between a hole and an outer
520	    /// polygon.
521	    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
522	        let mut p = outer_node;
523	        let hx = self.nodes[hole].x;
524	        let hy = self.nodes[hole].y;
525	        let mut qx = f64::NEG_INFINITY;
526	        let mut m = NIL;
527	
528	        // find a segment intersected by a ray from the hole's leftmost vertex to
529	        // the left; segment's endpoint with lesser x will be potential connection
530	        // vertex
531	        loop {
532	            let pn = self.nodes[p].next;
533	            let (py, pny) = (self.nodes[p].y, self.nodes[pn].y);
534	            if hy <= py && hy >= pny && pny != py {
535	                let (px, pnx) = (self.nodes[p].x, self.nodes[pn].x);
536	                let x = px + (hy - py) / (pny - py) * (pnx - px);
537	                if x <= hx && x > qx {
538	                    qx = x;
539	                    m = if px < pnx { p } else { pn };
540	                    if x == hx {
541	                        // hole touches outer segment; pick leftmost endpoint
542	                        return m;
543	                    }
544	                }
545	            }
546	            p = pn;
547	            if p == outer_node {
548	                break;
549	            }
550	        }
551	
552	        if m == NIL {
553	            return NIL;
554	        }
555	
556	        // look for points inside the triangle of hole vertex, segment intersection
557	        // and endpoint; if there are no points found, we have a valid connection;
558	        // otherwise choose the vertex of the polygon with the least x
559	        let stop = m;
560	        let mut tan_min = f64::INFINITY;
561	        let mx = self.nodes[m].x;
562	        let my = self.nodes[m].y;
563	
564	        p = m;
565	        loop {
566	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
567	            if hx >= px
568	                && px >= mx
569	                && hx != px
570	                && self.point_in_triangle(
571	                    if hy < my { hx } else { qx },
572	                    hy,
573	                    mx,
574	                    my,
575	                    if hy < my { qx } else { hx },
576	                    hy,
577	                    px,
578	                    py,
579	                )
580	            {
581	                let tan_cur = (hy - py).abs() / (hx - px); // tangential
582	
583	                if self.locally_inside(p, hole)
584	                    && (tan_cur < tan_min
585	                        || (tan_cur == tan_min
586	                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
587	                {
588	                    m = p;
589	                    tan_min = tan_cur;
590	                }
591	            }
592	
593	            p = self.nodes[p].next;
594	            if p == stop {
595	                break;
596	            }
597	        }
598	
599	        m
600	    }
601	}
