1	//! Geometric predicates over arena nodes.
2	//!
3	//! Every comparison here is performed on `f64` exactly as the reference
4	//! implementation does: no epsilons, no reordering of the arithmetic. The
5	//! triangulation of a self-intersecting ring is decided by the sign of these
6	//! expressions, so the operand order is load-bearing.
7	
8	use super::node::NIL;
9	use super::Earcut;
10	
11	impl Earcut {
12	    /// Signed area of the triangle `(p, q, r)`, doubled.
13	    pub(super) fn area(&self, p: usize, q: usize, r: usize) -> f64 {
14	        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
15	        (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
16	    }
17	
18	    /// Check if two points are equal.
19	    pub(super) fn equals(&self, p1: usize, p2: usize) -> bool {
20	        let (p1, p2) = (&self.nodes[p1], &self.nodes[p2]);
21	        p1.x == p2.x && p1.y == p2.y
22	    }
23	
24	    #[allow(clippy::too_many_arguments)]
25	    pub(super) fn point_in_triangle(
26	        &self,
27	        ax: f64,
28	        ay: f64,
29	        bx: f64,
30	        by: f64,
31	        cx: f64,
32	        cy: f64,
33	        px: f64,
34	        py: f64,
35	    ) -> bool {
36	        (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
