//! Z-order (Morton) curve indexing used to prune the point-in-ear search.
//!
//! Only reached for inputs with more than 80 vertices in total; below that the
//! triangulator does the linear scan in [`Earcut::is_ear`].

use super::node::NIL;
use super::Earcut;

impl Earcut {
    /// Z-order of a point given the current bounding box, interleaving the bits of
    /// the two coordinates.
    pub(crate) fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF_00FF;
        x = (x | (x << 4)) & 0x0F0F_0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF_00FF;
        y = (y | (y << 4)) & 0x0F0F_0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }

    /// Interlink every ring node into a sorted z-order linked list.
    pub(crate) fn index_curve(&mut self, start: usize) {
        let mut p = start;

        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
            self.nodes[p].prev_z = prev;
            self.nodes[p].next_z = next;
            p = next;
            if p == start {
                break;
            }
        }

        // `p` is back at `start`; break the ring open into a plain list.
        let prev_z = self.nodes[p].prev_z;
        self.nodes[prev_z].next_z = NIL;
        self.nodes[p].prev_z = NIL;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked list merge sort, ordering by `z`.
    pub(crate) fn sort_linked(&mut self, list: usize) -> usize {
        let mut list = list;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size: i32 = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NIL {
                        break;
                    }
                }
                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NIL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }
}

