// star-shaped simple polygon on an integer grid: angular sweep with varying integer radii
fn star(cx: i64, cy: i64, n: usize, rmin: i64, rmax: i64, rng: &mut Rng, rev: bool) -> Vec<[f64;2]> {
    let mut v: Vec<[f64;2]> = Vec::new();
    for k in 0..n {
        let ang = k as f64 / n as f64 * std::f64::consts::PI * 2.0;
        let r = (rmin + rng.u((rmax-rmin+1) as u64) as i64) as f64;
        // snap to integers so ties in slope/tangent are common
        let x = (cx as f64 + r*ang.cos()).round();
        let y = (cy as f64 + r*ang.sin()).round();
        if let Some(l) = v.last() { if *l == [x,y] { continue; } }
        v.push([x,y]);
    }
    v.dedup();
    if rev { v.reverse(); }
    v
}

fn main() {
    let mut rng = Rng(0xC0FFEE1234);
    let mut ndiff = 0usize;
    let trials = 400_000;
    for t in 0..trials {
        let mut poly: Vec<Vec<[f64;2]>> = Vec::new();
        poly.push(star(0, 0, 5 + rng.u(8) as usize, 8, 14, &mut rng, false));
        let nh = 1 + rng.u(3) as usize;
        for _ in 0..nh {
            let cx = rng.u(9) as i64 - 4;
            let cy = rng.u(9) as i64 - 4;
            poly.push(star(cx, cy, 3 + rng.u(4) as usize, 1, 3, &mut rng, true));
        }
        if poly.iter().any(|r| r.len() < 3) { continue; }
        let a = ea::earcut(&poly);
        let b = eb::earcut(&poly);
        if a != b {
