            if ndiff <= 2 {
                println!("trial {} DIFF\n  poly={:?}\n  rust-as-is={:?}\n  cpp-form  ={:?}", t, poly, a, b);
            }
        }
    }
    println!("sectorContainsSector-induced differing trials: {} / {}", ndiff, trials);
}
